@pytest.mark.parametrize( ("title", "size", "outcome", "candidates"), [ # SYNTHETIC titles for the rule's limits: the stored pages hold no title of these shapes. # The size already holds its pack: nothing is added or repeated. ("Example Paste, 4 oz (Pack of 4)", "4 oz (Pack of 4)", "trailing_segments", ()), ("Example Soda, 12 fl oz, 12 Pack Cans", "12 fl oz, 12 Pack Cans", "trailing_segments", ()), # The same pack quantity on both sides is one statement, in any spelling. ("(2-Pack) Example Soda, 2 Pack, 12 oz", "2 Pack, 12 oz", "trailing_segments", ()), # "2 pack" is not found inside "12 Pack". ("(2 pack) Example Soda, 12 Pack", "2 pack, 12 Pack", "multipack_in_title", ("2 pack", "12 Pack")), # Without brackets, one pack is not a multipack. ("Example 1-Pack Soap, 12 oz", "12 oz", "trailing_segments", ()), # Two different quantities and nothing to tell them apart: neither is chosen, the size stands. ("Example 2-Pack Soap 3-Pack Refill, 12 oz", "12 oz", "trailing_segments", ("2-Pack", "3-Pack")), # A bracket tells them apart. ("(2 pack) Example 3-Pack Soap, 12 oz", "2 pack, 12 oz", "multipack_in_title", ("2 pack", "12 oz")), # Not a quantity of packs: a model number and a word. ("Example Model#2-Pack Soap, 12 oz", "12 oz", "trailing_segments", ()), ("Example Family Pack Soap, 12 oz", "12 oz", "trailing_segments", ()), ], ) # fmt: skip def test_the_limits_of_keeping_a_multipack_beside_the_size( title: str, size: str, outcome: str, candidates: tuple[str, ...] ) -> None: out = wrec.size_from_title(title) > assert (out.value, out.outcome, out.candidates) == (size, outcome, candidates) E AssertionError: assert ('12 oz', 'tr...segments', ()) == ('12 oz', 'tr...k', '3-Pack')) E E At index 2 diff: () != ('2-Pack', '3-Pack') E Use -v to get more diff
