env = {'engine': Engine(postgresql+psycopg://postgres:***@127.0.0.1:49844/walmart_collector_test?connect_timeout=15), 'facto..._contest_store=False, notes='Client-assigned store, 3900 Fountain Square Pl, Waukegan, IL 60085; Pickup prices.'), ...}
def test_a_page_budget_never_stops_what_earlier_reads_already_established( env: dict[str, Any], # noqa: F811 ) -> None: """Release 1.5.1. The never-read products come first in the queue, so until 1.5.0 a spent budget ended the loop before the products whose page was already saved: they stayed blank at no saving of any request. The live campaign's repeat of 2026-10-31 showed it: the same product blank in one run and filled in the next. With one page never read behind the budget, a second pass of the loop hid this, so two are left.""" first, _ = _run(env, detail=DetailConfig(max_per_run=1)) read_first = {item for _, item in _detail_calls(env)} assert len(read_first) == 1 env["mock"].calls.clear() second, _ = _run(env, detail=DetailConfig(max_per_run=1)) read_second = [item for _, item in _detail_calls(env)] assert len(read_second) == 1 and read_second[0] not in read_first # still goes to a never-read one rows = field_rows(env, second) by_disposition: dict[str, set[str]] = {} for key, row in rows.items(): by_disposition.setdefault(row["upc"]["disposition"], set()).add(key.removeprefix("wm:")) > assert by_disposition[disp.RECOVERED] == read_first # no request, and each names the run that read it ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ E KeyError: 'recovered_from_saved_detail'
